{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "자전거 교통안전교육 인증 시 공공자전거 요금 감면 대상 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "자전거 교통안전교육 인증을 받은 사람은 공공자전거 이용요금 감면 대상자에 해당한다. 조례 제12조의3제2항제6호에서 감면 대상자 기준으로 제13조제6항에 따른 자전거 교통안전교육 인증을 받은 사람을 명시하고 있기 때문이다. 다만 감면율 및 운영에 관한 사항은 시장이 따로 정한다.",
          "b_ids": "자전거:제12조의3제2항제6호, 자전거:제12조의3제1항, 자전거:제12조의3제3항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "공공자전거 요금 감면율을 정하는 주체",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "감면 대상자별 감면율 및 운영에 관한 사항은 시장이 따로 정한다. 조례 제12조의3제3항에서 제2항에 따른 감면 대상자별 감면율 및 운영에 관한 사항을 시장이 따로 정하도록 규정하고 있기 때문이다.",
          "b_ids": "자전거:제12조의3제3항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
